#include "ringbuf.h"
#include <stdlib.h>
#include <string.h>

struct ringbuf {
    uint8_t *buf;
    size_t capacity;
    size_t head;  /* write index */
    size_t tail;  /* read index */
    size_t count; /* bytes currently stored */
};

ringbuf_t *rb_create(size_t capacity) {
    if (capacity == 0) return NULL;
    ringbuf_t *rb = malloc(sizeof(*rb));
    if (!rb) return NULL;
    rb->buf = malloc(capacity);
    if (!rb->buf) { free(rb); return NULL; }
    rb->capacity = capacity;
    rb->head = 0;
    rb->tail = 0;
    rb->count = 0;
    return rb;
}

void rb_destroy(ringbuf_t *rb) {
    if (!rb) return;
    free(rb->buf);
    free(rb);
}

static size_t free_space(const ringbuf_t *rb) {
    return rb->capacity - rb->count;
}

size_t rb_write(ringbuf_t *rb, const uint8_t *data, size_t len) {
    if (!rb || !data || len == 0) return 0;
    size_t avail = free_space(rb);
    if (avail == 0) return 0;
    size_t n = len < avail ? len : avail;

    /* First segment: head to end of buffer */
    size_t first = rb->capacity - rb->head;
    if (n <= first) {
        memcpy(rb->buf + rb->head, data, n);
        rb->head = (rb->head + n) % rb->capacity;
    } else {
        memcpy(rb->buf + rb->head, data, first);
        size_t second = n - first;
        memcpy(rb->buf, data + first, second);
        rb->head = second;
    }
    rb->count += n;
    return n;
}

size_t rb_read(ringbuf_t *rb, uint8_t *out, size_t len) {
    if (!rb || !out || len == 0) return 0;
    if (rb->count == 0) return 0;
    size_t n = len < rb->count ? len : rb->count;

    size_t first = rb->capacity - rb->tail;
    if (n <= first) {
        memcpy(out, rb->buf + rb->tail, n);
        rb->tail = (rb->tail + n) % rb->capacity;
    } else {
        memcpy(out, rb->buf + rb->tail, first);
        size_t second = n - first;
        memcpy(out + first, rb->buf, second);
        rb->tail = second;
    }
    rb->count -= n;
    return n;
}

size_t rb_peek(const ringbuf_t *rb, uint8_t *out, size_t len) {
    if (!rb || !out || len == 0) return 0;
    if (rb->count == 0) return 0;
    size_t n = len < rb->count ? len : rb->count;

    size_t first = rb->capacity - rb->tail;
    if (n <= first) {
        memcpy(out, rb->buf + rb->tail, n);
    } else {
        memcpy(out, rb->buf + rb->tail, first);
        size_t second = n - first;
        memcpy(out + first, rb->buf, second);
    }
    return n;
}

size_t rb_size(const ringbuf_t *rb) {
    if (!rb) return 0;
    return rb->count;
}

size_t rb_capacity(const ringbuf_t *rb) {
    if (!rb) return 0;
    return rb->capacity;
}

void rb_clear(ringbuf_t *rb) {
    if (!rb) return;
    rb->head = 0;
    rb->tail = 0;
    rb->count = 0;
}

#include <stdio.h>
#include <string.h>
#include <assert.h>
#include "ringbuf.h"

int main(void) {
    /* Test create/destroy */
    ringbuf_t *rb = rb_create(8);
    assert(rb != NULL);
    assert(rb_capacity(rb) == 8);
    assert(rb_size(rb) == 0);

    /* Test write/read cycle */
    const uint8_t msg[] = {1, 2, 3, 4, 5};
    size_t w = rb_write(rb, msg, sizeof(msg));
    assert(w == 5);
    assert(rb_size(rb) == 5);

    uint8_t buf[8] = {0};
    size_t r = rb_read(rb, buf, sizeof(buf));
    assert(r == 5);
    assert(memcmp(buf, msg, 5) == 0);
    assert(rb_size(rb) == 0);

    /* Test wrap-around: fill most of the buffer, write to force wrap */
    memset(msg, 0xAA, sizeof(msg));
    uint8_t fill[16];
    memset(fill, 0xBB, sizeof(fill));
    for (size_t i = 0; i < 7; i++) {
        rb_write(rb, fill+i, 1); /* tail advances to 7 */
    }
    assert(rb_size(rb) == 7);

    /* Write more — must wrap */
    uint8_t more[] = {0xCC, 0xDD, 0xEE};
    w = rb_write(rb, more, sizeof(more));
    assert(w == 1); /* only 1 byte fits (capacity=8, count=7) */
    assert(rb_size(rb) == 8);

    /* Read all and verify order */
    memset(buf, 0, sizeof(buf));
    r = rb_read(rb, buf, 8);
    assert(r == 8);
    uint8_t expected[] = {0xBB,0xBB,0xBB,0xBB,0xBB,0xBB,0xBB,0xCC};
    assert(memcmp(buf, expected, 8) == 0);

    /* Test full buffer */
    w = rb_write(rb, more, sizeof(more));
    assert(w == 0);

    /* Clear and reuse */
    rb_clear(rb);
    assert(rb_size(rb) == 0);
    w = rb_write(rb, msg, sizeof(msg));
    assert(w == 5);

    /* Test peek */
    size_t p = rb_peek(rb, buf, 3);
    assert(p == 3);
    assert(memcmp(buf, msg, 3) == 0);
    assert(rb_size(rb) == 5); /* peek doesn't remove */

    /* Partial write (write larger than free space) */
    rb_clear(rb);
    uint8_t big[20];
    w = rb_write(rb, big, 20);
    assert(w == 8); /* only capacity fits */

    NULL; // suppress unused variable warning for r/p
    rb_destroy(rb);
    rb_destroy(NULL); /* must not crash */

    printf("All tests passed.\n");
    return 0;
}

